  "promptTemplate": "Evaluation run {{id}}. Requirement: {{requirement}}",
  "defaults": { "budget": { "maxTurns": 12, "maxCostUsd": 0.6 }, "minRecall": 0.75, "expectedStatus": ["complete"] },
  "globalForbiddenClaims": [],
  "cases": [
    {
      "id": "ARCH-02",
      "title": "Serve $lastn for 500 subjects",
      "requirement": "A dashboard will call $lastn with 500 subjects. Can the design handle it?",
      "contextFiles": ["sample-app/src/main/java/org/example/fhir/service/ObservationService.java"],
      "expectedFindings": [
        { "id": "F1", "concept": "performance problem", "match": [["performance"]], "severity": null }
      ],
      "forbiddenClaims": []
    }
  ]
}

implementation.content:
{
  "suite": "architecture",
  "datasetVersion": "1.0.0",
  "agent": "architect",
  "description": "20 golden tasks for the architect agent against AI-SDLC/sample-app. Each case fixes the requirement and the context files, and states what a correct answer must mention, what it must never claim, and how severe the main findings are. Matching is case-insensitive regex; an expected finding is covered when every group in `match` has at least one hit (AND of ORs). Severity is checked on the Findings-table row whose text hits the first group.",
  "promptTemplate": "Evaluation run {{id}} (run_id eval-{{id}}, step 03). Do not create or edit any file: return your complete handoff as your final message.\n\nRequirement: {{requirement}}\n\nRead these files before answering: {{contextFiles}}.",
  "defaults": {
    "budget": {
      "maxTurns": 12,
      "maxCostUsd": 0.6
    },
    "minRecall": 0.75,
    "expectedStatus": [
      "complete",
      "needs-human"
    ]
  },
  "globalForbiddenClaims": [
    {
      "id": "G-HAPI",
      "claim": "The sample app uses HAPI FHIR (it does not; see docs/adr/0001-fhir-lite-instead-of-hapi.md)",
      "patterns": [
        "\\b(uses|using|built on|based on|relies on|via|through) (the )?HAPI",
        "HAPI[- ]FHIR[^.\\n]{0,40}\\b(is|are) (used|configured|on the classpath)",
        "\\b(IParser|FhirContext|IBundleProvider)\\b"
      ]
    },
    {
      "id": "G-REDIS",
      "claim": "An existing Redis (or other) cache is in place (there is no cache in the sample app)",
      "patterns": [
        "\\b(existing|current|already configured|already deployed)\\b[^.\\n]{0,40}\\b(Redis|Memcached|Hazelcast|Caffeine)\\b",
        "\\b(Redis|Memcached|Hazelcast|Caffeine)\\b[^.\\n]{0,40}\\b(already|currently) (used|configured|in place|deployed)\\b",
        "@Cacheable[^.\\n]{0,40}\\b(already|existing|currently)\\b",
        "\\bexisting (cache|caching layer)\\b"
      ]
    },
    {
      "id": "G-KAFKA",
      "claim": "A message broker already exists (there is none)",
      "patterns": [
        "\\b(existing|current)\\b[^.\\n]{0,30}\\b(Kafka|RabbitMQ|message broker)\\b",
        "\\b(Kafka|RabbitMQ)\\b[^.\\n]{0,30}\\b(already|currently) (used|configured|deployed)\\b"
      ]
    }
  ],
  "cases": [
    {
      "id": "ARCH-01",
      "title": "Paginate Patient and Observation searches",
      "category": "api-design",
      "evalTypes": [
        "regression"
      ],
      "requirement": "Add paging to GET /fhir/Patient and GET /fhir/Observation so a clinic with 200,000 patients cannot pull an unbounded Bundle in one response.",
      "contextFiles": [
        "context/standards/api-standards.md",
        "sample-app/src/main/java/org/example/fhir/service/PatientService.java",
        "sample-app/src/main/java/org/example/fhir/repository/PatientRepository.java",
        "sample-app/src/main/java/org/example/fhir/api/Bundle.java"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "Use the planned _count parameter (default 20, max 100) from api-standards.md",
          "match": [
            [
              "_count"
            ],
            [
              "\\b100\\b"
            ]
          ],
          "severity": null
        },
        {
          "id": "F2",
          "concept": "Searches are unbounded today: repository methods return a full List",
          "match": [
            [
              "unbounded",
              "no pagination",
              "not paginated"
            ],
            [
              "findByFamilyNameIgnoreCaseOrderByIdAsc",
              "findByPatientIdOrderByEffectiveDateTimeDesc",
              "List<Patient>"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F3",
          "concept": "Bundle.total currently equals the returned list size; paging changes its meaning and needs next links",
          "match": [
            [
              "Bundle"
            ],
            [
              "\\btotal\\b"
            ],
            [
              "next",
              "link"
            ]
          ],
          "severity": [
            "low",
            "medium"
          ]
        }
      ],
      "forbiddenClaims": []
    },
    {
      "id": "ARCH-02",
      "title": "Serve $lastn for 500 subjects",
      "category": "performance",
      "evalTypes": [
        "regression"
      ],
      "requirement": "A population-health dashboard will call GET /fhir/Observation/$lastn with up to 500 subjects per request. Assess whether the current design can handle it and what must change.",
      "contextFiles": [
        "sample-app/src/main/java/org/example/fhir/service/ObservationService.java",
        "sample-app/src/main/java/org/example/fhir/repository/ObservationRepository.java",
        "sample-app/src/main/resources/db/migration/V1__init.sql",
        "sample-app/docs/KNOWN_DEFECTS.md"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "N+1 in ObservationService.lastN: two queries per subject",
          "match": [
            [
              "N\\+1",
              "queries per subject",
              "per-subject quer"
            ],
            [
              "lastN",
              "\\$lastn"
            ]
          ],
          "severity": [
            "high",
            "critical"
          ]
        },
        {
          "id": "F2",
          "concept": "Replace the loop with one set-based query",
          "match": [
            [
              "IN \\(:ids\\)",
              "set-based",
              "single query",
              "window function",
              "max\\(effective_date_time\\)"
            ]
          ],
          "severity": null
        },
        {
          "id": "F3",
          "concept": "Cap the number of subjects per request",
          "match": [
            [
              "\\bcap\\b",
              "limit",
              "maximum"
            ],
            [
              "subjects"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F4",
          "concept": "Existing index ix_observation_patient_code (patient_id, code) supports the set-based query",
          "match": [
            [
              "ix_observation_patient_code",
              "\\(patient_id, code\\)"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "lastN already batches its queries",
          "patterns": [
            "lastN[^.\\n]{0,60}already (batch|uses a set-based|uses a single)",
            "already (uses|issues) (a )?(single|set-based|batched) quer"
          ]
        }
      ]
    },
    {
      "id": "ARCH-03",
      "title": "Switch resource ids to UUIDs",
      "category": "data-model",
      "evalTypes": [
        "regression"
      ],
      "requirement": "Security asked us to stop exposing sequential ids. Propose how to move Patient and Observation ids to UUIDs without breaking existing clients.",
      "contextFiles": [
        "context/architecture/overview.md",
        "sample-app/src/main/resources/db/migration/V1__init.sql",
        "sample-app/src/main/java/org/example/fhir/api/ObservationMapper.java",
        "docs/adr/0000-template.md"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "BIGINT identity ids are enumerable",
          "match": [
            [
              "BIGINT",
              "IDENTITY",
              "surrogate",
              "sequential"
            ],
            [
              "enumerat"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F2",
          "concept": "Add a new Flyway migration; never edit V1__init.sql",
          "match": [
            [
              "V2__",
              "new (Flyway )?migration"
            ],
            [
              "V1__init"
            ]
          ],
          "severity": null
        },
        {
          "id": "F3",
          "concept": "observation.patient_id foreign key must be migrated with the patient key",
          "match": [
            [
              "patient_id"
            ],
            [
              "fk_observation_patient",
              "foreign key",
              "\\bFK\\b"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F4",
          "concept": "ObservationMapper.parseSubject uses Long.valueOf and rejects UUID references",
          "match": [
            [
              "parseSubject",
              "Long\\.valueOf"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F5",
          "concept": "Record the decision in an ADR",
          "match": [
            [
              "\\bADR\\b"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "Recommends editing the applied V1 migration",
          "patterns": [
            "\\b(modify|edit|change|update|alter) (the )?V1__init\\.sql"
          ]
        },
        {
          "id": "C2",
          "claim": "Ids are already UUIDs",
          "patterns": [
            "already (use|uses|using) UUID"
          ]
        }
      ]
    },
    {
      "id": "ARCH-04",
      "title": "Replace HTTP Basic with OAuth2 / SMART-on-FHIR",
      "category": "security",
      "evalTypes": [
        "regression",
        "hallucination"
      ],
      "critical": true,
      "requirement": "Replace HTTP Basic with OAuth2 bearer tokens (SMART-on-FHIR style scopes) issued by the hospital identity provider.",
      "contextFiles": [
        "sample-app/src/main/java/org/example/fhir/config/SecurityConfig.java",
        "sample-app/src/test/java/org/example/fhir/SecurityTest.java",
        "sample-app/pom.xml",
        "context/security/phi-and-secrets-policy.md"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "Current auth is HTTP Basic with an InMemoryUserDetailsManager",
          "match": [
            [
              "HTTP Basic",
              "httpBasic"
            ],
            [
              "InMemoryUserDetailsManager",
              "in-memory users"
            ]
          ],
          "severity": [
            "info",
            "low",
            "medium"
          ]
        },
        {
          "id": "F2",
          "concept": "Map CLINICIAN/ADMIN roles to token scopes or claims, keeping DELETE ADMIN-only",
          "match": [
            [
              "CLINICIAN"
            ],
            [
              "scope",
              "claim"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F3",
          "concept": "SecurityTest must be rewritten for bearer tokens (401/403 cases)",
          "match": [
            [
              "SecurityTest"
            ]
          ],
          "severity": null
        },
        {
          "id": "F4",
          "concept": "spring-boot-starter-oauth2-resource-server is not in pom.xml yet",
          "match": [
            [
              "oauth2-resource-server"
            ]
          ],
          "severity": null
        },
        {
          "id": "F5",
          "concept": "Record the decision in an ADR",
          "match": [
            [
              "\\bADR\\b"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "JWT/OAuth2/Keycloak is already configured",
          "patterns": [
            "\\b(JWT|OAuth2?|Keycloak)\\b[^.\\n]{0,40}\\b(already|currently) (configured|in place|used|enabled)",
            "\\bexisting (JWT|OAuth2?|Keycloak)\\b"
          ]
        }
      ]
    },
    {
      "id": "ARCH-05",
      "title": "Make final Observations immutable",
      "category": "domain-rules",
      "evalTypes": [
        "regression",
        "hallucination"
      ],
      "requirement": "Enforce glossary business rule 4: Observations with status final are immutable and corrections create an amended Observation.",
      "contextFiles": [
        "context/domain/fhir-lite-glossary.md",
        "sample-app/src/main/java/org/example/fhir/api/ObservationController.java",
        "sample-app/src/main/java/org/example/fhir/service/ObservationService.java",
        "sample-app/src/main/resources/db/migration/V1__init.sql"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "There is no update endpoint for Observation today, so the rule is trivially true now and must be enforced when one is added",
          "match": [
            [
              "ObservationController"
            ],
            [
              "no PUT",
              "no update",
              "no @PutMapping",
              "only GET and POST",
              "does not expose (a )?PUT"
            ]
          ],
          "severity": [
            "info",
            "low"
          ]
        },
        {
          "id": "F2",
          "concept": "Corrections create a new amended Observation",
          "match": [
            [
              "amended"
            ]
          ],
          "severity": [
            "medium",
            "low"
          ]
        },
        {
          "id": "F3",
          "concept": "Enforce in ObservationService, not the controller",
          "match": [
            [
              "ObservationService"
            ]
          ],
          "severity": null
        },
        {
          "id": "F4",
          "concept": "status is an unconstrained VARCHAR(32) with no CHECK constraint",
          "match": [
            [
              "status"
            ],
            [
              "CHECK",
              "VARCHAR\\(32\\)",
              "not constrained",
              "unconstrained"
            ]
          ],
          "severity": [
            "low",
            "medium"
          ]
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "An Observation PUT/update endpoint already exists",
          "patterns": [
            "PUT /fhir/Observation/\\{id\\}[^.\\n]{0,40}\\b(exists|already|currently)\\b",
            "\\bexisting (PUT|update) (endpoint|method|operation)\\b"
          ]
        }
      ]
    },
    {
      "id": "ARCH-06",
      "title": "Reject Observations for inactive patients",
      "category": "domain-rules",
      "evalTypes": [
        "regression"
      ],
      "requirement": "Enforce glossary business rule 3: an Observation's subject must resolve to an existing, active Patient.",
      "contextFiles": [
        "context/domain/fhir-lite-glossary.md",
        "sample-app/src/main/java/org/example/fhir/service/ObservationService.java",
        "sample-app/src/test/java/org/example/fhir/ObservationApiTest.java"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "ObservationService.create checks existence but not the active flag",
          "match": [
            [
              "ObservationService\\.create",
              "create\\("
            ],
            [
              "isActive",
              "\\bactive\\b"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F2",
          "concept": "Reject with 422 via FhirApiException.unprocessable",
          "match": [
            [
              "422",
              "unprocessable"
            ]
          ],
          "severity": null
        },
        {
          "id": "F3",
          "concept": "Add a regression test in ObservationApiTest",
          "match": [
            [
              "ObservationApiTest"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "The active rule is already enforced",
          "patterns": [
            "\\bactive\\b[^.\\n]{0,40}already (checked|enforced|validated)"
          ]
        }
      ]
    },
    {
      "id": "ARCH-07",
      "title": "Add an Encounter resource",
      "category": "domain-model",
      "evalTypes": [
        "hallucination"
      ],
      "requirement": "Add an Encounter resource so Observations can be grouped by clinic visit.",
      "contextFiles": [
        "context/domain/fhir-lite-glossary.md",
        "context/architecture/overview.md",
        "docs/adr/0001-fhir-lite-instead-of-hapi.md"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "The glossary defines only four resource types; Encounter expands the domain and the glossary",
          "match": [
            [
              "Encounter"
            ],
            [
              "glossary"
            ]
          ],
          "severity": [
            "medium",
            "low"
          ]
        },
        {
          "id": "F2",
          "concept": "New V2 migration plus entity/repository/service/controller following the layering",
          "match": [
            [
              "V2__"
            ],
            [
              "EncounterService",
              "service layer",
              "layering"
            ]
          ],
          "severity": null
        },
        {
          "id": "F3",
          "concept": "Observation needs an optional encounter reference",
          "match": [
            [
              "encounter_id",
              "Observation\\.encounter",
              "encounter reference"
            ]
          ],
          "severity": [
            "medium",
            "low"
          ]
        },
        {
          "id": "F4",
          "concept": "ADR, and FHIR-lite stays non-conformant (ADR-0001)",
          "match": [
            [
              "\\bADR\\b"
            ],
            [
              "0001",
              "FHIR-lite",
              "not (a )?conformant"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "HAPI FHIR provides the Encounter model here",
          "patterns": [
            "HAPI[^.\\n]{0,40}\\bEncounter\\b"
          ]
        }
      ]
    },
    {
      "id": "ARCH-08",
      "title": "Ship audit events to a separate sink",
      "category": "observability",
      "evalTypes": [
        "hallucination"
      ],
      "requirement": "Compliance wants audit events retained for six years in a separate store from application logs.",
      "contextFiles": [
        "sample-app/src/main/java/org/example/fhir/audit/AuditLogger.java",
        "sample-app/src/main/resources/application.yml",
        "sample-app/k8s/deployment.yaml",
        "context/security/phi-and-secrets-policy.md"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "Audit events already go to a dedicated AUDIT logger",
          "match": [
            [
              "AUDIT\"? logger",
              "getLogger\\(\"AUDIT\"\\)"
            ]
          ],
          "severity": [
            "info",
            "low"
          ]
        },
        {
          "id": "F2",
          "concept": "No dedicated appender or sink is configured; only logging.level.AUDIT is set",
          "match": [
            [
              "appender",
              "logback"
            ]
          ],
          "severity": [
            "medium"
          ]
        },
        {
          "id": "F3",
          "concept": "The ids-only rule must survive the new sink (no PHI)",
          "match": [
            [
              "ids only",
              "ids-only"
            ],
            [
              "PHI"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F4",
          "concept": "Pods log to stdout; collection happens outside the app",
          "match": [
            [
              "stdout"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "An ELK/Fluentd/Splunk pipeline already exists",
          "patterns": [
            "\\b(ELK|Elasticsearch|Fluentd|Fluent Bit|Splunk)\\b[^.\\n]{0,30}\\b(already|currently)\\b",
            "\\bexisting (ELK|Elasticsearch|Fluentd|Fluent Bit|Splunk)\\b"
          ]
        }
      ]
    },
    {
      "id": "ARCH-09",
      "title": "Bulk $export of all patients",
      "category": "security",
      "evalTypes": [
        "hallucination"
      ],
      "critical": true,
      "requirement": "Research wants a nightly bulk export of all Patients and Observations via a FHIR-style $export operation.",
      "contextFiles": [
        "context/security/threat-model.md",
        "context/security/phi-and-secrets-policy.md",
        "sample-app/src/main/java/org/example/fhir/config/SecurityConfig.java",
        "sample-app/src/main/java/org/example/fhir/audit/AuditLogger.java"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "Mass PHI export: restrict to ADMIN (or a dedicated role) and require approval",
          "match": [
            [
              "ADMIN",
              "dedicated role"
            ],
            [
              "export"
            ]
          ],
          "severity": [
            "high",
            "critical"
          ]
        },
        {
          "id": "F2",
          "concept": "Must be asynchronous (202 + status polling), not a synchronous unbounded response",
          "match": [
            [
              "async",
              "asynchronous",
              "\\b202\\b"
            ]
          ],
          "severity": [
            "medium",
            "high"
          ]
        },
        {
          "id": "F3",
          "concept": "Every export is audited through AuditLogger",
          "match": [
            [
              "AuditLogger"
            ]
          ],
          "severity": null
        },
        {
          "id": "F4",
          "concept": "Threat model: availability / DoS row applies",
          "match": [
            [
              "threat.model"
            ],
            [
              "denial of service",
              "availability",
              "DoS"
            ]
          ],
          "severity": null
        }
      ],
      "forbiddenClaims": [
        {
          "id": "C1",
          "claim": "Spring Batch is already on the classpath",
          "patterns": [
            "Spring Batch[^.\\n]{0,40}\\b(already|on the classpath|is used|existing)\\b"
          ]
        },
        {
          "id": "C2",
          "claim": "An $export endpoint already exists",
          "patterns": [
            "\\bexisting (\\$export|export) (endpoint|operation)\\b"
          ]
        }
      ]
    },
    {
      "id": "ARCH-10",
      "title": "Serve multiple clinics from one deployment",
      "category": "data-model",
      "evalTypes": [
        "regression"
      ],
      "requirement": "Two more clinics join. Each clinic issues its own MRNs and must never see another clinic's patients. Propose a multi-tenant design.",
      "contextFiles": [
        "sample-app/src/main/resources/db/migration/V1__init.sql",
        "sample-app/src/main/java/org/example/fhir/repository/PatientRepository.java",
        "sample-app/src/main/java/org/example/fhir/config/SecurityConfig.java",
        "context/domain/fhir-lite-glossary.md"
      ],
      "expectedFindings": [
        {
          "id": "F1",
          "concept": "uq_patient_mrn makes MRN globally unique; clinics' MRNs will collide",
          "match": [
            [
              "uq_patient_mrn",
              "UNIQUE \\(mrn\\)"
            ]
          ],
          "severity": [
            "high"
          ]
        },
        {
          "id": "F2",
          "concept": "Add tenant_id to patient and observation and filter every query",
          "match": [
            [
              "tenant_id"
            ]
          ],
